import{_ as t,o as a,h as s,a2 as r}from"./chunks/framework.wsBNORhl.js";const h=JSON.parse('{"title":"@ui5/builder/tasks/runTask","description":"","frontmatter":{"prev":false,"next":false},"headers":[],"relativePath":"api/module-@ui5_builder_tasks_runTask.md","filePath":"api/module-@ui5_builder_tasks_runTask.md"}'),o={name:"api/module-@ui5_builder_tasks_runTask.md"};function d(i,e,c,n,l,p){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="ui5-builder-tasks-runtask" tabindex="-1">@ui5/builder/tasks/runTask <a class="header-anchor" href="#ui5-builder-tasks-runtask" aria-label="Permalink to &quot;@ui5/builder/tasks/runTask&quot;">​</a></h1><p>Runs a UI5 Builder task without a build cache.</p><p>A task default-exports a factory <code>defineTask(options) =&gt; descriptor</code>. A traditional descriptor&#39;s <code>task</code> function runs directly. For a descriptor with a <code>steps</code> array, this runner is the no-cache counterpart to the cached step runner in <code>@ui5/project</code> (which <code>@ui5/builder</code> cannot import, the dependency direction being <code>@ui5/cli -&gt; @ui5/project -&gt; @ui5/builder</code>): it runs every step in order, fans out every map step&#39;s <code>keys</code> set, threads <code>needs</code> returns in memory, and buffers a concurrent map step&#39;s writes so they flush in key order. It replaces the per-task batch fallback tasks used to hand-write for standalone (direct or programmatic) invocation of <code>@ui5/builder</code>.</p><p>Delta selection, CAS-backed returns, tag replay and signature computation are cache concerns and are absent here; every step runs.</p><p><strong>Description:</strong> Runs a UI5 Builder task without a build cache.</p><p>A task default-exports a factory <code>defineTask(options) =&gt; descriptor</code>. A traditional descriptor&#39;s <code>task</code> function runs directly. For a descriptor with a <code>steps</code> array, this runner is the no-cache counterpart to the cached step runner in <code>@ui5/project</code> (which <code>@ui5/builder</code> cannot import, the dependency direction being <code>@ui5/cli -&gt; @ui5/project -&gt; @ui5/builder</code>): it runs every step in order, fans out every map step&#39;s <code>keys</code> set, threads <code>needs</code> returns in memory, and buffers a concurrent map step&#39;s writes so they flush in key order. It replaces the per-task batch fallback tasks used to hand-write for standalone (direct or programmatic) invocation of <code>@ui5/builder</code>.</p><p>Delta selection, CAS-backed returns, tag replay and signature computation are cache concerns and are absent here; every step runs.</p><p><strong>Source:</strong> <a href="https://github.com/UI5/cli/blob/main/packages//builder/lib/tasks/runTask.js" target="_blank" rel="noopener noreferrer">builder/lib/tasks/runTask.js</a>, <a href="https://github.com/UI5/cli/blob/main/packages//builder/lib/tasks/runTask.js#L181" target="_blank" rel="noopener noreferrer">line 181</a></p><h3 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h3><h4 id="static-default-definetask-parameters-rarr-promise-lt-undefined" tabindex="-1"><div class="jsdoc-object" id=".default"><span class="type-signature">(static) </span>default<span class="signature">(defineTask, parameters)</span><span class="type-signature"> → {Promise&lt;undefined&gt;}</span></div> <a class="header-anchor" href="#static-default-definetask-parameters-rarr-promise-lt-undefined" aria-label="Permalink to &quot;&lt;div class=&#39;jsdoc-object&#39; id=&#39;.default&#39;&gt;&lt;span class=&quot;type-signature&quot;&gt;(static) &lt;/span&gt;default&lt;span class=&quot;signature&quot;&gt;(defineTask, parameters)&lt;/span&gt;&lt;span class=&quot;type-signature&quot;&gt; &amp;rarr; {Promise&amp;lt;undefined&gt;}&lt;/span&gt;&lt;/div&gt;&quot;">​</a></h4><p><strong>Description:</strong> Runs a UI5 Builder task without a build cache.</p><p><strong>Source:</strong> <a href="https://github.com/UI5/cli/blob/main/packages//builder/lib/tasks/runTask.js" target="_blank" rel="noopener noreferrer">builder/lib/tasks/runTask.js</a>, <a href="https://github.com/UI5/cli/blob/main/packages//builder/lib/tasks/runTask.js#L228" target="_blank" rel="noopener noreferrer">line 228</a></p><h5 id="parameters" tabindex="-1">Parameters: <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters:&quot;">​</a></h5><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>defineTask</code></td><td>function</td><td>Task factory <code>defineTask(options) =&gt; descriptor</code></td></tr><tr><td><code>parameters</code></td><td>object</td><td><br><em>Properties:</em><table class="props"><thead><tr><th>Name</th><th>Type</th><th>Attributes</th><th class="last">Description</th></tr></thead><tbody><tr><td class="name"><code>workspace</code></td><td class="type"><a href="@ui5_fs_DuplexCollection">@ui5/fs/DuplexCollection</a></td><td class="attributes"></td><td class="description last">Workspace to read and write files</td></tr><tr><td class="name"><code>dependencies</code></td><td class="type"><a href="@ui5_fs_AbstractReader">@ui5/fs/AbstractReader</a></td><td class="attributes">optional</td><td class="description last">Reader to read dependency files</td></tr><tr><td class="name"><code>taskUtil</code></td><td class="type">@ui5/builder/tasks/TaskUtil | object</td><td class="attributes">optional</td><td class="description last">TaskUtil, passed to the task body or each step</td></tr><tr><td class="name"><code>options</code></td><td class="type">object</td><td class="attributes">optional</td><td class="description last">Task options, passed to the factory, task body, or each step</td></tr></tbody></table></td></tr></tbody></table><h5 id="returns" tabindex="-1">Returns: <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns:&quot;">​</a></h5><p>Resolves once the task has run and all writes are complete</p><p><strong>Type:</strong> Promise&lt;undefined&gt;</p><h3 id="type-definitions" tabindex="-1">Type Definitions <a class="header-anchor" href="#type-definitions" aria-label="Permalink to &quot;Type Definitions&quot;">​</a></h3><h4 id="taskdescriptor" tabindex="-1"><div class="jsdoc-object" id="~TaskDescriptor">TaskDescriptor</div> <a class="header-anchor" href="#taskdescriptor" aria-label="Permalink to &quot;&lt;div class=&#39;jsdoc-object&#39; id=&#39;~TaskDescriptor&#39;&gt;TaskDescriptor&lt;/div&gt;&quot;">​</a></h4><p><strong>Description:</strong> The descriptor a task factory returns from its default export, from <a href="https://ui5.github.io/cli/stable/pages/Configuration/#specification-versions" target="_blank" rel="noreferrer">Specification Version</a> 5.0. It carries the whole task in one object: the task body, its optional callbacks, and an optional declared Specification Version.</p><p>The factory must stay pure and cheap. UI5 CLI calls it once per build, early also for the build signature, so it must not read or write resources, and it must not import heavy processors. The work happens in the <code>task</code> body or in the step callbacks.</p><p><strong>Source:</strong> <a href="https://github.com/UI5/cli/blob/main/packages//builder/lib/tasks/runTask.js" target="_blank" rel="noopener noreferrer">builder/lib/tasks/runTask.js</a>, <a href="https://github.com/UI5/cli/blob/main/packages//builder/lib/tasks/runTask.js#L199" target="_blank" rel="noopener noreferrer">line 199</a></p><h5 id="properties" tabindex="-1">Properties: <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties:&quot;">​</a></h5><table class="props"><thead><tr><th>Name</th><th>Type</th><th>Attributes</th><th>Default</th><th class="last">Description</th></tr></thead><tbody><tr><td class="name"><code>steps</code></td><td class="type">Array&lt;object&gt;</td><td class="attributes">optional</td><td class="default"></td><td class="description last">The build steps of a cache-aware, step-based task. Give exactly one of<br> <code>steps</code> or <code>task</code>. A step is a scalar step <code>{name, needs?, run}</code> or a<br> map step <code>{name, needs?, sequential?, keys, each}</code>; the build cache re-runs only the steps,<br> and within a map step only the keys, whose inputs changed.</td></tr><tr><td class="name"><code>task</code></td><td class="type">function</td><td class="attributes">optional</td><td class="default"></td><td class="description last">The task body <code>async (parameters) =&gt; Promise&lt;undefined&gt;</code> of a<br> traditional task. Give exactly one of <code>steps</code> or <code>task</code>.</td></tr><tr><td class="name"><code>requiresDependencies</code></td><td class="type">boolean</td><td class="attributes">optional</td><td class="default"><code>false</code></td><td class="description last">Whether the task needs access to the resources of the<br> project&#39;s dependencies. When <code>false</code>, the <code>dependencies</code> reader is not provided.</td></tr><tr><td class="name"><code>determineRequiredDependencies</code></td><td class="type">function</td><td class="attributes">optional</td><td class="default"></td><td class="description last">Optional callback that reduces the set of dependencies<br> made available through the <code>dependencies</code> reader.</td></tr><tr><td class="name"><code>determineBuildSignature</code></td><td class="type">function</td><td class="attributes">optional</td><td class="default"></td><td class="description last">Optional callback that contributes to the project&#39;s build<br> signature, so a change outside the project&#39;s own resources can invalidate the task&#39;s cached output.</td></tr><tr><td class="name"><code>determineExpectedOutput</code></td><td class="type">function</td><td class="attributes">optional</td><td class="default"></td><td class="description last">Optional callback that declares the task&#39;s expected output.</td></tr><tr><td class="name"><code>specVersion</code></td><td class="type">string</td><td class="attributes">optional</td><td class="default"></td><td class="description last">Optional Specification Version. When set, it must be equal to the task<br> extension&#39;s configured Specification Version.</td></tr></tbody></table><p>The descriptor a task factory returns from its default export, from <a href="https://ui5.github.io/cli/stable/pages/Configuration/#specification-versions" target="_blank" rel="noreferrer">Specification Version</a> 5.0. It carries the whole task in one object: the task body, its optional callbacks, and an optional declared Specification Version.</p><p>The factory must stay pure and cheap. UI5 CLI calls it once per build, early also for the build signature, so it must not read or write resources, and it must not import heavy processors. The work happens in the <code>task</code> body or in the step callbacks.</p><h5 id="type" tabindex="-1">Type: <a class="header-anchor" href="#type" aria-label="Permalink to &quot;Type:&quot;">​</a></h5><ul><li>object</li></ul>',28)])])}const b=t(o,[["render",d]]);export{h as __pageData,b as default};
